for path,d in PAGES.items():
 depth=len([x for x in path.split('/') if x]); prefix='../'*depth or './'
 def localize(s):
  def href(m):
   target=m.group(1); base,sep,anchor=target.partition('#')
   if base.endswith('/'):base+='index.html'
   return 'href="'+prefix+base.lstrip('/')+(('#'+anchor) if sep else '')+'"'
  return re.sub(r'href="(/[^"]*)"',href,s).replace('src="/','src="'+prefix)
 url='https://educandoconchispa.com'+path
 person={'@type':'Person','@id':'https://educandoconchispa.com/#jose','name':'José Luis Latorre Delgado','url':'https://educandoconchispa.com/sobre-mi/','sameAs':['https://www.linkedin.com/in/jose-luis-latorre-delgado']}
 org={'@type':'Organization','@id':'https://educandoconchispa.com/#organization','name':'Educando con chIspA','url':'https://educandoconchispa.com/','logo':'https://educandoconchispa.com/assets/logo.svg','founder':{'@id':person['@id']}}
 node={'@type':d['kind'],'@id':url+'#page','url':url,'name':d['title'],'description':d['description'],'inLanguage':'es','publisher':{'@id':org['@id']}}
 if d['kind']=='Article':node.update({'headline':d['title'],'author':{'@id':person['@id']}})
 links=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==path else '')+f'>{t}</a>' for t,u in NAV)
 head=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(d['title'])}</title><meta name="description" content="{escape(d['description'],quote=True)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#071015"><link rel="canonical" href="{url}"><meta property="og:title" content="{escape(d['title'],quote=True)}"><meta property="og:description" content="{escape(d['description'],quote=True)}"><meta property="og:type" content="{'article' if d['kind']=='Article' else 'website'}"><meta property="og:url" content="{url}"><meta property="og:image" content="https://educandoconchispa.com/assets/og.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':[person,org,node]},ensure_ascii=False)}</script></head>'''
 shell=f'''<body><a class="skip" href="#main">Saltar al contenido</a><header class="topbar"><div class="wrap nav"><a class="brand" href="/" aria-label="Educando con chIspA, inicio"><img src="/assets/logo.svg" width="275" height="70" alt="Educando con chIspA"></a><button class="menu" aria-controls="navigation" aria-expanded="false" type="button">Menú</button><nav id="navigation" class="links" aria-label="Navegación principal">{links}<a class="nav-cta" href="/contacto/">Hablemos ↗</a></nav></div></header><main id="main">{d['body']}</main><footer class="footer"><div class="wrap"><div class="footer-top"><div><strong>EDUCANDO CON chIspA</strong><br>La tecnología ayuda. La chIspA la pones tú.</div><div class="footer-links"><a href="/charlas/">Charlas</a><a href="/contacto/">Contacto</a><a href="https://www.linkedin.com/in/jose-luis-latorre-delgado">LinkedIn</a><a href="https://ia.educandoconchispa.com/privacidad.html">Privacidad actual</a></div></div><div class="footer-bottom"><span>© 2026 Educando con chIspA · Tarazona, Zaragoza</span><button class="motion-control" type="button" aria-pressed="false">Pausar movimiento</button></div></div></footer></body></html>'''
 directory=OUT/path.strip('/');directory.mkdir(parents=True,exist_ok=True);(directory/'index.html').write_text(localize(head+shell),encoding='utf-8')
